  max-height: 700px;
  display: flex;
  flex-direction: column;

  .container-header {
    /* 固定顶部，不滚动 */
    flex-shrink: 0;
  }
  .container-content {
    /* 内容滚动 */
    flex: 1;
    overflow-y: auto;
